function beep(kind="tap"){if(!settings.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.type=kind==="clutch"?"triangle":"sine";o.frequency.value=kind==="win"?740:kind==="slash"?380:kind==="clutch"?92:kind==="alert"?660:520;const duration=kind==="win"?.45:kind==="clutch"?.28:.1;g.gain.setValueAtTime(kind==="clutch"?.08:.035,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);o.start();o.stop(c.currentTime+duration+.01);if(kind==="clutch"){const o2=c.createOscillator();o2.connect(g);o2.frequency.value=126;o2.start(c.currentTime+.14);o2.stop(c.currentTime+.22);}setTimeout(()=>c.close(),600);}catch{}}
