async function uploadAvatar(file){if(!user||!file)return;try{const bitmap=await createImageBitmap(file),side=Math.min(bitmap.width,bitmap.height),canvas=document.createElement("canvas");canvas.width=canvas.height=128;const ctx=canvas.getContext("2d");ctx.drawImage(bitmap,(bitmap.width-side)/2,(bitmap.height-side)/2,side,side,0,0,128,128);let q=.84,data=canvas.toDataURL("image/jpeg",q);while(data.length>27000&&q>.25){q-=.1;data=canvas.toDataURL("image/jpeg",q);}if(data.length>28000)throw new Error("Photo could not be compressed below 20 KB.");await update(ref(db,`users/${user.uid}`),{avatarUrl:data,avatarPreset:null});userData={...userData,avatarUrl:data,avatarPreset:null};updateProfileUI();renderProfile();toast("Profile photo updated.");}catch(e){toast(e.message||"Could not process that image.");}}
function attachMailbox(){if(!user||!db)return;if(mailUnsub)mailUnsub();mailUnsub=onValue(ref(db,`users/${user.uid}/mailbox`),snap=>{const msgs=Object.entries(snap.val()||{}).filter(([,m])=>!m.deleted).sort((a,b)=>Number(b[1].createdAt||0)-Number(a[1].createdAt||0));const unread=msgs.filter(([,m])=>!m.read).length,badge=$("#mailbox-badge");badge.textContent=unread>9?"9+":unread;badge.classList.toggle("hidden",!unread);const box=$("#mailbox-list");if(!msgs.length){box.innerHTML='<div class="mail-empty"><span>✦</span><b>You are all caught up</b><small>Staff notes and game alerts will appear here.</small></div>';return;}box.innerHTML=msgs.map(([id,m])=>`<article class="mail-item ${m.read?"read":"unread"} theme-${escapeHtml(m.theme||"normal")}"><span class="mail-unread-dot"></span><div class="mail-main"><div class="mail-item-top"><b>${escapeHtml(m.subject||"Bingo 25 update")}</b><span class="mail-theme-badge">${escapeHtml((m.theme||"normal").toUpperCase())}</span><small>${formatTime(m.createdAt)}</small></div><p>${escapeHtml(m.body||"")}</p><small class="mail-sender">${escapeHtml(m.senderName||"Anlossa Group")}</small><div class="mail-actions">${m.read?"":`<button class="text-button" data-mail-read="${id}">Mark as read</button>`}<button class="text-button" data-mail-delete="${id}">Delete</button></div></div></article>`).join("");});}
function formatTime(stamp){if(!stamp)return"Just now";const d=new Date(Number(stamp));return Number.isNaN(d.getTime())?"Just now":d.toLocaleString([], {month:"short",day:"numeric",hour:"numeric",minute:"2-digit"});}
