function renderProgress(lines){$("#board-progress").innerHTML="BINGO".split("").map((c,i)=>`<span class="progress-letter ${i<lines?"done":""}">${c}</span>`).join("");}
function updateClutch(lines,game){const active=lines===4,board=$(".board-card"),banner=$("#clutch-banner");board.classList.toggle("clutch",active);banner.classList.toggle("hidden",!active);if(game){if(active&&!game.clutchSfx){game.clutchSfx=true;beep("clutch");}if(!active)game.clutchSfx=false;}}
function updateArena(){if(localGame){const g=localGame;renderBoard($("#my-board"),g.myBoard,g.calls,{disabled:g.phase!=="setup"&&!g.myTurn,selectedNumber:g.selectedNumber});renderStrikes($("#my-strikes"),g.myBoard,g.calls);const myLines=completedLines(g.myBoard,g.calls).length,oppLines=completedLines(g.oppBoard,g.calls).length;renderProgress(myLines);updateClutch(myLines,g);$("#ability-controls").classList.toggle("hidden",g.phase!=="playing");$("#ability-counter").textContent=`TACTICAL CHARGES · ${g.abilityCharges}`;$("#aegis-status").textContent=g.aegis?"AEGIS WARD ACTIVE":"";$$("[data-ability]").forEach(b=>b.disabled=!g.myTurn||g.abilityCharges<=0||g.abilityUsedTurn);$("#my-player-lines").textContent=`${myLines} / 5 lines`;$("#opponent-lines").textContent=`${oppLines} / 5 lines`;$("#called-list").textContent=g.calls.length?g.calls.join(" · "):"No numbers called yet";$("#my-turn-indicator").parentElement.classList.toggle("active-turn",g.phase==="playing"&&g.myTurn);$("#opponent-turn-indicator").parentElement.classList.toggle("active-turn",g.phase==="playing"&&!g.myTurn);$("#setup-controls").classList.toggle("hidden",g.phase!=="setup");$("#playing-controls").classList.toggle("hidden",g.phase!=="playing");$("#match-status-text").textContent=g.phase==="setup"?"BOARD SETUP":g.phase==="playing"?"MATCH IN PROGRESS":"MATCH COMPLETE";$("#arena-title").textContent=g.phase==="setup"?"Set your board.":g.phase==="playing"?(g.myTurn?"Your turn.":"Opponent's turn."):"Match complete.";$("#arena-subtitle").textContent=g.phase==="setup"?"Tap a pair of cells to swap them, or shuffle for a fresh arrangement.":g.phase==="playing"?(g.myTurn?"Choose any unmarked number from your grid.":"Watch the board. Your opponent is thinking."):"Review both boards and decide on a rematch.";$("#call-selected").disabled=!g.myTurn||g.selectedNumber==null||Date.now()-lastTurnAt<350;$("#call-selected").textContent=g.selectedNumber?`Call ${g.selectedNumber}`:"Call selected number";setBoardSkin(g.skin||"notebook");}else if(roomState){const me=roomState.boards?.[user.uid]||setupBoard;setupBoard=me.slice();const calls=roomState.calledNumbers||[];const lines=completedLines(me,calls).length;updateClutch(lines,roomState);$("#ability-controls").classList.toggle("hidden",roomState.status!=="playing");const charges=roomState.abilities?.charges?.[user.uid]??2,used=(roomState.abilities?.usedTurn?.[user.uid]===roomState.turnStartedAt);$("#ability-counter").textContent=`TACTICAL CHARGES · ${charges}`;$("#aegis-status").textContent=roomState.abilities?.aegis?.[user.uid]?"AEGIS WARD ACTIVE":"";$$("[data-ability]").forEach(b=>b.disabled=roomState.turn!==user.uid||charges<=0||used);renderBoard($("#my-board"),me,calls,{disabled:roomState.status!=="setup"&&roomState.turn!==user.uid,selectedNumber:roomState.selectedNumber});renderStrikes($("#my-strikes"),me,calls);renderProgress(lines);const enemy=roomState.players?.find(x=>x!==user.uid);$("#opponent-name").textContent=roomState.playerNames?.[enemy]||"Opponent";$("#my-player-lines").textContent=`${lines} / 5 lines`;$("#called-list").textContent=calls.join(" · ")||"No numbers called yet";$("#setup-controls").classList.toggle("hidden",roomState.status!=="setup");$("#playing-controls").classList.toggle("hidden",roomState.status!=="playing");$("#match-status-text").textContent=roomState.status.toUpperCase();$("#my-turn-indicator").parentElement.classList.toggle("active-turn",roomState.turn===user.uid);$("#opponent-turn-indicator").parentElement.classList.toggle("active-turn",roomState.turn!==user.uid);$("#call-selected").disabled=roomState.turn!==user.uid||!roomState.selectedNumber||Date.now()-lastTurnAt<350;$("#call-selected").textContent=roomState.selectedNumber?`Call ${roomState.selectedNumber}`:"Call selected number";setBoardSkin(userData?.equippedSkin||currentRank().skin);}}
function onCell(idx){if(localGame){const g=localGame;if(g.phase==="setup"){if(selectedCell===null){selectedCell=idx;}else if(selectedCell!==idx){[g.myBoard[selectedCell],g.myBoard[idx]]=[g.myBoard[idx],g.myBoard[selectedCell]];selectedCell=null;}else selectedCell=null;renderBoard($("#my-board"),g.myBoard,g.calls);return;}if(g.phase==="playing"&&g.myTurn&&Date.now()-lastTurnAt>=350&&!g.calls.includes(g.myBoard[idx])){g.selectedNumber=g.myBoard[idx];updateArena();}return;}
  if(roomState?.status==="setup"){if(selectedCell===null)selectedCell=idx;else if(idx!==selectedCell){const b=[...(roomState.boards?.[user.uid]||setupBoard)];[b[selectedCell],b[idx]]=[b[idx],b[selectedCell]];setupBoard=b;selectedCell=null;}else selectedCell=null;renderBoard($("#my-board"),setupBoard,roomState.calledNumbers||[]);return;}if(roomState?.status==="playing"&&roomState.turn===user.uid&&Date.now()-lastTurnAt>=350){const n=(roomState.boards?.[user.uid]||[])[idx];if(!(roomState.calledNumbers||[]).includes(n)){roomState.selectedNumber=n;$("#call-selected").disabled=false;$("#call-selected").textContent=`Call ${n}`;}}}
function renderTrainingSelector(){const box=$("#training-options");if(!box)return;const rp=Number(userData?.rp||100),owner=user?.uid===PRIMARY_OWNER_UID;box.innerHTML=TRAINING_TIERS.map(t=>{const unlocked=owner||rp>=t.floor;return`<button class="training-tier ${unlocked?"":"locked"}" data-training="${t.id}" ${unlocked?"":"disabled"}><span class="training-tier-icon">${unlocked?"◈":"🔒"}</span><span><b>${t.name}</b><small>${t.desc}</small></span>${unlocked?`<i>${t.floor?`RP ${t.floor}+`:"OPEN"}</i>`:`<i>Requires ${t.name==="Void Abyss"?"Void Rank — 2,200+ RP":`${rankFor(t.floor).name} — ${t.floor}+ RP`}</i>`}</button>`;}).join("");}
function startBot(difficulty){if(user&&!difficulty){renderTrainingSelector();modal("training-modal");return;}difficulty=difficulty||"easy";const tier=TRAINING_TIERS.find(t=>t.id===difficulty)||TRAINING_TIERS[0],owner=user?.uid===PRIMARY_OWNER_UID;if(user&&!owner&&Number(userData?.rp||100)<tier.floor){toast(`Requires ${tier.name} training unlock.`);return;}closeModals();cleanupRoom();selectedCell=null;localGame={myBoard:randBoard(),oppBoard:randBoard(),calls:[],phase:"setup",myTurn:true,selectedNumber:null,skin:userData?.equippedSkin||currentRank().skin,ready:false,difficulty,turnDeadline:0,abilityCharges:2,abilityUsedTurn:false,aegis:false,opponentAegis:false};$("#arena-mode-label").textContent=`TRAINING · ${tier.name.toUpperCase()} · 0 RP`;$("#opponent-name").textContent=`${tier.name} Training AI`;$("#opponent-label").textContent="TRAINING AI";setView("arena-view");updateArena();startSetupCountdown();}
function linePotential(board,calls,n){let score=0;for(const line of LINES){if(!line.some(i=>board[i]===n))continue;const count=line.filter(i=>calls.includes(board[i])).length;if(count>=4){score+=512;continue;}if(count>0)score+=[1,4,16,64][count-1];}const index=board.indexOf(n),row=Math.floor(index/5),col=index%5;if(index===12)score+=10;if(row===col||row+col===4)score+=3;if([7,13,19].includes(n))score+=2;return score;}
function botPick(){const g=localGame;if(!g)return null;const available=g.oppBoard.filter(n=>!g.calls.includes(n));if(!available.length)return null;if(g.difficulty==="easy")return available[Math.floor(Math.random()*available.length)];let best=available[0],bestScore=-Infinity;for(const n of available){const own=linePotential(g.oppBoard,g.calls,n);if(g.difficulty==="normal"){let score=0;for(const line of LINES){if(!line.some(i=>g.oppBoard[i]===n))continue;const marked=line.filter(i=>g.calls.includes(g.oppBoard[i])).length;if(marked===2)score+=8;if(marked===3)score+=24;}score+=Math.random()*.2;if(score>bestScore){bestScore=score;best=n;}continue;}let score=own;if(g.difficulty==="extreme"||g.difficulty==="void"){const opp=linePotential(g.myBoard,g.calls,n),index=g.oppBoard.indexOf(n),intersection=LINES.filter(line=>line.includes(index)).length;score+=intersection*3-opp*.82;if([7,13,19].includes(n))score+=5;}if(g.difficulty==="void"){const after=[...g.calls,n],playerChoices=g.myBoard.filter(v=>!after.includes(v)),botChoices=g.oppBoard.filter(v=>!after.includes(v));let playerBest=0;for(const p of playerChoices)playerBest=Math.max(playerBest,linePotential(g.myBoard,after,p));let botNext=0;for(const q of botChoices)botNext=Math.max(botNext,linePotential(g.oppBoard,after,q)-linePotential(g.myBoard,after,q)*.45);score+=botNext*.55-playerBest*.72;}score+=Math.random()*.01;if(score>bestScore){bestScore=score;best=n;}}return best;}

function startSetupCountdown(){let s=15;$("#setup-countdown").textContent=`Auto-lock in ${s}s`;clearInterval(readyTimer);readyTimer=setInterval(()=>{s--;$("#setup-countdown").textContent=`Auto-lock in ${s}s`;if(s<=0){clearInterval(readyTimer);readyLocal();}},1000);}
function readyLocal(){if(!localGame||localGame.phase!=="setup")return;if(!validBoard(localGame.myBoard)){toast("Board must contain every number from 1 to 25 exactly once.");return;}localGame.phase="playing";localGame.myTurn=true;localGame.selectedNumber=null;clearInterval(readyTimer);readyTimer=null;lastTurnAt=Date.now();updateArena();startTurnClock();toast("Board locked. You take the first turn.");}
function localCall(n,actor){const g=localGame;if(!g||g.phase!=="playing"||g.calls.includes(n))return;const previousActor=actor;g.calls.push(n);g.selectedNumber=null;g.myTurn=!g.myTurn;g.abilityUsedTurn=actor==="you";lastTurnAt=Date.now();beep("slash");vibrate();speakCallout(`Number ${n}`);updateArena();const ml=completedLines(g.myBoard,g.calls).length,bl=completedLines(g.oppBoard,g.calls).length;if(ml>=5||bl>=5){const defenseWard=actor==="you"?g.opponentAegis:g.aegis,side=resolveLineWinner(ml,bl,actor==="you"?"player":"bot",defenseWard);finishLocal(side==="player"?"you":"bot");return;}if(previousActor==="bot"){g.aegis=false;g.abilityUsedTurn=false;}else g.opponentAegis=false;startTurnClock();if(!g.myTurn){clearTimeout(autoCallTimer);autoCallTimer=setTimeout(()=>{if(localGame?.phase==="playing"&&!localGame.myTurn)localCall(botPick(),"bot");},650+Math.random()*550);}}
function startTurnClock(){clearInterval(turnInterval);if(!localGame||localGame.phase!=="playing")return;localGame.turnDeadline=Date.now()+15000+(localGame.timeBonus||0);localGame.timeBonus=0;turnInterval=setInterval(()=>{if(!localGame||localGame.phase!=="playing"){clearInterval(turnInterval);return;}const seconds=Math.max(0,Math.ceil((localGame.turnDeadline-Date.now())/1000));$("#turn-timer").textContent=seconds;if(seconds<=0){clearInterval(turnInterval);if(localGame.myTurn){const choices=localGame.myBoard.filter(n=>!localGame.calls.includes(n));if(choices.length)localCall(choices[Math.floor(Math.random()*choices.length)],"you");}else if(!localGame.myTurn)localCall(botPick(),"bot");}},200);}
function useLocalAbility(type){const g=localGame;if(!g||g.phase!=="playing"||!g.myTurn||g.abilityCharges<=0||g.abilityUsedTurn)return toast("No tactical charge available this turn.");g.abilityCharges--;g.abilityUsedTurn=true;if(type==="sonar"){const choices=g.myBoard.filter(n=>!g.calls.includes(n));g.selectedNumber=choices.sort((a,b)=>linePotential(g.myBoard,g.calls,b)-linePotential(g.myBoard,g.calls,a))[0];$("#board-hint").textContent=`SONAR → ${g.selectedNumber} advances the most open lines`;toast(`Sonar found ${g.selectedNumber}.`);}else if(type==="chrono"){g.turnDeadline=Math.max(Date.now(),g.turnDeadline)+5000;$("#turn-timer").textContent=Math.ceil((g.turnDeadline-Date.now())/1000);toast("Chrono Surge +5 seconds.");}else if(type==="aegis"){g.aegis=true;toast("Aegis Ward active for the opponent's next turn.");}beep("tap");updateArena();}
function finishLocal(winner){localGame.phase="finished";clearInterval(turnInterval);clearTimeout(autoCallTimer);beep(winner==="you"?"win":"tap");const win=winner==="you";$("#result-title").textContent=win?"Victory.":"Defeat.";$("#result-summary").textContent="Local bot matches are for practice and never change your RP.";renderReveal($("#reveal-mine"),localGame.myBoard,localGame.calls);renderReveal($("#reveal-opponent"),localGame.oppBoard,localGame.calls);modal("result-modal");updateArena();}
function renderReveal(el,board,calls){el.innerHTML=board.map(n=>`<div class="reveal-cell ${calls.includes(n)?"marked":""}">${n}</div>`).join("");const svg=document.createElementNS("http://www.w3.org/2000/svg","svg");svg.setAttribute("viewBox","0 0 500 500");svg.setAttribute("preserveAspectRatio","none");svg.classList.add("reveal-strikes");completedLines(board,calls).forEach(idx=>{const l=LINE_DEFS[idx],line=document.createElementNS("http://www.w3.org/2000/svg","line");line.setAttribute("x1",l.a[0]);line.setAttribute("y1",l.a[1]);line.setAttribute("x2",l.b[0]);line.setAttribute("y2",l.b[1]);svg.appendChild(line);});el.appendChild(svg);}
function shuffleSetup(){if(localGame?.phase==="setup"){localGame.myBoard=randBoard();selectedCell=null;renderBoard($("#my-board"),localGame.myBoard,[]);}else if(roomState?.status==="setup"){setupBoard=randBoard();renderBoard($("#my-board"),setupBoard,[]);}}
function cleanupRoom(){if(roomChatUnsub){roomChatUnsub();roomChatUnsub=null;}if(roomUnsub){roomUnsub();roomUnsub=null;}if(opponentPresenceUnsub){opponentPresenceUnsub();opponentPresenceUnsub=null;}clearTimeout(disconnectTimer);clearInterval(turnInterval);clearInterval(readyTimer);clearTimeout(autoCallTimer);activeRoomId=null;roomState=null;localGame=null;}
function firebaseInit(){if(!configReady()){console.warn("Firebase config is incomplete; local training remains available.");return false;}try{fbApp=getApps().find(app=>app.name==="[DEFAULT]")||initializeApp(firebaseConfig);auth=getAuth(fbApp);db=getDatabase(fbApp,firebaseConfig.databaseURL);return Boolean(auth&&db);}catch(e){console.error("Firebase v10 initialization failed:",e.code||e.message);toast("Online services could not connect. Local training is still available.");return false;}}
async function authStart(){if(!configReady()){toast("Online play needs Firebase config in app.js. You can play the bot right now.");return;}if(!auth||!db){toast("Online services are unavailable right now. Local training is ready.");return;}try{const p=new GoogleAuthProvider();await signInWithPopup(auth,p);}catch(e){if(["auth/popup-blocked","auth/popup-closed-by-user","auth/cancelled-popup-request"].includes(e.code)){try{await signInWithRedirect(auth,new GoogleAuthProvider());}catch(err){toast(err.message);}}else toast(e.message||"Sign-in failed.");}}
async function onSignedIn(u){user=u;$("#auth-action").classList.add("hidden");if(profileUnsub){profileUnsub();profileUnsub=null;}const userRef=ref(db,`users/${u.uid}`);try{const snap=await get(userRef);userData=snap.val()||{};if(u.uid===PRIMARY_OWNER_UID&&userData.role!=="owner"){await update(userRef,{role:"owner"});userData.role="owner";}if(!userData.username){$("#username-view").classList.remove("hidden");setView("username-view");}else{if(!snap.exists())await update(userRef,{username:null,rp:100,role:"player",status:"online",unlockedSkins:{notebook:true},unlockedTitles:{Rookie:true},createdAt:serverTimestamp()});attachProfile();setView("lobby-view");attachSquad();attachLiveAlerts();await recoverRoom();}attachPresence();attachInvites();attachChat();attachFriends();attachMailbox();attachAnnouncement();attachGuild();updateProfileUI();const challenge=takeSavedInvite();if(challenge){$("#challenge-name").value=challenge;toast(`Challenge ${challenge} when you're ready.`);}}catch(e){console.error(e);toast("Could not load your player profile. Check Firebase rules.");}}
function attachProfile(){profileUnsub=onValue(ref(db,`users/${user.uid}`),s=>{userData=s.val()||{};updateProfileUI();});}
function openFriendsDrawer(){if(!user)return authStart();const drawer=$("#friends-drawer");drawer.classList.remove("hidden");drawer.classList.add("open");drawer.setAttribute("aria-hidden","false");$("#friends-drawer-backdrop").classList.remove("hidden");}
function closeFriendsDrawer(){const drawer=$("#friends-drawer");drawer.classList.remove("open");drawer.classList.add("hidden");drawer.setAttribute("aria-hidden","true");$("#friends-drawer-backdrop").classList.add("hidden");}
function drawSquadMembers(){const container=$("#squad-stage-members");if(!container)return;const members=Object.entries(squadData?.members||{}),leader=squadData?.leaderUid===user?.uid;container.innerHTML=members.length?members.map(([uid,m])=>{const me=uid===user?.uid,mp=uid===squadData.leaderUid,visual=designRank(m);return`<article class="stage-character ${me?"is-you":""}" data-member="${uid}" data-rank="${visual.id}" data-aura="${escapeHtml(m.aura||"none")}"><span class="stage-emote ${m.emote?.at&&Date.now()-m.emote.at<3000?"show":""}" id="stage-emote-${uid}">${m.emote?.at&&Date.now()-m.emote.at<3000?escapeHtml(m.emote.text):""}</span><div class="character-aura ${escapeHtml(m.frame||visual.frame)}"><span class="stage-character-flag">${rankFlagSvg(visual)}</span><svg class="character-svg" viewBox="0 0 90 130" aria-label="${escapeHtml(m.username||"Player")} character"><defs><linearGradient id="char-${uid}" x1="0" y1="0" x2="1" y2="1"><stop stop-color="${AVATAR_PRESETS.find(a=>a.id===m.avatarPreset)?.color||"#9cf36b"}"/><stop offset="1" stop-color="#292846"/></linearGradient></defs><path d="M45 5 76 18 70 48 45 68 20 48 14 18Z" fill="url(#char-${uid})"/><circle cx="45" cy="37" r="17" fill="#111722"/><path d="M12 125c3-32 15-48 33-48s30 16 33 48" fill="url(#char-${uid})"/><path d="M22 115 45 96 68 115" fill="none" stroke="#fff8" stroke-width="3"/></svg></div><div class="stage-nameplate"><b>${escapeHtml(m.username||"Player")}</b><small>${escapeHtml(visual.rank)} · ${escapeHtml(m.title||"Rookie")}</small><small>${escapeHtml(DESIGN_CATALOG.skins[m.equippedSkin]?.name||"Ruled Notebook")} · ${escapeHtml(DESIGN_CATALOG.auras[m.aura]?.name||"No aura")}</small><span class="stage-role ${mp?"mp-badge":""}">${mp?"♛ MP":escapeHtml(m.roleBadge||"PLAYER")}</span></div>${leader&&!me?`<button class="transfer-mp" data-transfer-mp="${uid}">Make leader</button><button class="kick-party" data-kick-member="${uid}">Remove</button>`:""}<button class="stage-emote-hit" data-emote-self="${me?"true":"false"}" aria-label="Emote as ${escapeHtml(m.username||"Player")}">⋯</button></article>`;}).join(""):'<div class="squad-empty">Party stage ready — invite up to three allies.</div>';const isLeader=squadData?.leaderUid===user?.uid;$("#squad-mode").value=squadData?.mode||"unranked_1v1";$("#squad-mode").disabled=!isLeader;$("#squad-leader-label").textContent=isLeader?"♛ You are Party Leader · MP":"Party Leader controls the queue";$("#squad-name-display").textContent=squadData?.name||"Your party, your queue.";$("#party-member-count-home").textContent=`${members.length} / 4 members`;$("#squad-mode-note").textContent=isLeader?"Only the MP controls the active queue mode.":"Queue mode is locked by the MP.";$("#squad-leave").classList.toggle("hidden",members.length<=1);}
function setSquadStageMessage(message, retry=false, create=false){const container=$("#squad-stage-members");if(!container)return;container.innerHTML=`<div class="squad-empty">${escapeHtml(message)}${create?'<button type="button" class="button button-primary" data-create-party>Create a Party</button>':''}${retry?'<button type="button" class="text-button" data-retry-squad>Retry</button>':''}</div>`;}
async function createPersonalSquad(){if(!user||!db)return;partyCollection="parties";const uid=user.uid,profile=userData||{},name=`${profile.username||"Player"}'s Party`;await set(ref(db,`parties/${uid}`),{leaderUid:uid,mode:"unranked_1v1",name,emblemCrest:"lion",createdAt:serverTimestamp(),members:{[uid]:{username:profile.username||"Player",avatarPreset:profile.avatarPreset||"nova",rank:currentRank().name,rp:Number(profile.rp||100),title:profile.equippedTitle||currentRank().title,roleBadge:profile.role||"PLAYER",frame:profile.equippedFrame||"frame-initiate",aura:profile.equippedAura||"none",status:"online"}}});await set(ref(db,`users/${uid}/squadId`),uid);toast("Your party is ready. Invite allies by username.");}
function attachSquad(){if(!user||!db){setSquadStageMessage("Sign in to create or join a party.");return;}if(squadPointerUnsub){squadPointerUnsub();squadPointerUnsub=null;}if(squadInviteUnsub){squadInviteUnsub();squadInviteUnsub=null;}if(squadUnsub){squadUnsub();squadUnsub=null;}squadId=null;squadData=null;squadCreating=false;squadPointerUnsub=onValue(ref(db,`users/${user.uid}/squadId`),async pointer=>{const next=pointer.val();if(!next){squadId=null;squadData=null;setSquadStageMessage("No party yet. Create one, or accept a friend’s party invite.",false,true);renderGuildParty();return;}if(next===squadId&&squadUnsub)return;if(squadUnsub){squadUnsub();squadUnsub=null;}const modern=await get(ref(db,`parties/${next}`));if(modern.exists())partyCollection="parties";else{const legacy=await get(ref(db,`squads/${next}`));if(!legacy.exists()){squadId=null;squadData=null;setSquadStageMessage("Party data is unavailable. Ask the leader for a new invite.",false,true);renderGuildParty();return;}partyCollection="squads";}squadId=next;squadUnsub=onValue(partyRef(next),snap=>{const value=snap.val();if(!value){squadData=null;setSquadStageMessage("Party data is unavailable. Ask the leader for a new invite.",false,true);renderGuildParty();return;}squadData=value;drawSquadMembers();renderGuildParty();},error=>{console.warn("Party listener failed:",error.code||error.message);squadData=null;setSquadStageMessage("Party stage unavailable. Check Firebase rules.",true);});},error=>{console.warn("Party pointer listener failed:",error.code||error.message);setSquadStageMessage("Could not connect to the party stage. Check Firebase rules.",true);});squadInviteUnsub=onValue(ref(db,`users/${user.uid}/squadInvites`),snap=>{const invites=Object.entries(snap.val()||{}).filter(([,v])=>v.status==="pending");$("#squad-invites-list").innerHTML=invites.length?invites.map(([id,v])=>`<article class="drawer-invite"><b>@${escapeHtml(v.fromName||"Player")} invited you</b><small>Party queue · ${escapeHtml(v.mode||"Unranked")}</small><div><button class="text-button" data-squad-accept="${id}">Accept</button><button class="text-button" data-squad-decline="${id}">Decline</button></div></article>`).join(""):'<p class="muted">No pending invites.</p>';},error=>{console.warn("Party invite listener failed:",error.code||error.message);$("#squad-invites-list").innerHTML='<p class="muted">Party invites unavailable.</p>';});}
async function inviteToSquad(uid){if(!user||!squadId||!squadData)return toast("Create or join a party first.");if(squadData.leaderUid!==user.uid)return toast("Only the party leader can invite allies.");const count=Object.keys(squadData.members||{}).length;if(count>=4)return toast("Party is full (4/4).");if(squadData.members?.[uid])return toast("Already in your party.");try{const r=push(ref(db,`users/${uid}/squadInvites`));await set(r,{from:user.uid,fromName:userData.username,squadId,partyCollection,mode:squadData.mode||"Unranked",status:"pending",createdAt:serverTimestamp()});toast("Party invite sent.");}catch(e){toast(e.message||"Could not invite this friend.");}}
