async function reserveUsername(event){event.preventDefault();const input=$("#username-input"),rawUsername=input.value;const cleanName=rawUsername.trim().toLowerCase();if(!/^[a-z0-9_]{3,15}$/.test(cleanName)){toast("Use 3–15 letters, numbers, or underscores.");return;}if(!user||!db){userData={username:cleanName,rp:100,role:"player"};updateProfileUI();setView("lobby-view");return;}const usernameRef=ref(db,"usernames/"+cleanName);try{const existing=await get(usernameRef);if(existing.exists()&&existing.val()!==user.uid){toast("That username is already taken.");return;}if(!existing.exists())await set(usernameRef,user.uid);const role=user.uid===PRIMARY_OWNER_UID?"owner":"player";await update(ref(db,"users/"+user.uid),{username:cleanName,rp:100,role,status:"online",unlockedSkins:{notebook:true},unlockedTitles:{Rookie:true},createdAt:serverTimestamp()});userData={...(userData||{}),username:cleanName,rp:100,role,status:"online"};attachProfile();attachPresence();attachInvites();attachChat();attachFriends();attachMailbox();attachAnnouncement();attachSquad();attachGuild();attachLiveAlerts();updateProfileUI();setView("lobby-view");const challenge=takeSavedInvite();if(challenge){$("#challenge-name").value=challenge;toast(`Challenge ${challenge} when you're ready.`);}}catch(error){console.error("Username reservation Firebase write failed:",error.code,error.message);toast(error.message||"Username reservation failed.");}}
async function createInvite(){if(!user){await authStart();return;}const name=$("#challenge-name").value.trim();if(!/^[A-Za-z0-9_]{3,15}$/.test(name)){toast("Enter a valid username first.");return;}try{const sn=await get(ref(db,`usernames/${name.toLowerCase()}`));const target=sn.val();if(!target){toast("No player has that username.");return;}if(target===user.uid){toast("You can't challenge yourself.");return;}const [statusSnap,nameSnap,banSnap]=await Promise.all([get(ref(db,`users/${target}/status`)),get(ref(db,`users/${target}/username`)),get(ref(db,`users/${target}/bannedUntil`))]);const targetData={status:statusSnap.val(),username:nameSnap.val(),bannedUntil:banSnap.val()};if(targetData.status!=="online"||(targetData.bannedUntil&&targetData.bannedUntil!==0&&targetData.bannedUntil>Date.now())){toast(targetData.status==="in_game"?"That player is already in a match.":"That player is offline or unavailable.");return;}const sent=await get(ref(db,`invites/${user.uid}`));const reciprocal=Object.entries(sent.val()||{}).find(([,v])=>v.from===target&&v.status==="pending");if(reciprocal){await acceptInvite(reciprocal[0],reciprocal[1],true);return;}const inviteId=push(ref(db,`invites/${target}`)).key;const payload={from:user.uid,fromName:userData.username,fromRank:currentRank().name,fromTitle:userData.equippedTitle||currentRank().title,status:"pending",createdAt:serverTimestamp()};await set(ref(db,`invites/${target}/${inviteId}`),payload);await set(ref(db,`outgoingInvites/${user.uid}/${inviteId}`),{targetUid:target,targetName:targetData.username,status:"pending",createdAt:serverTimestamp()});toast(`Challenge sent to @${targetData.username}.`);}catch(e){toast(e.message||"Could not send invite.");}}
