async function listenRoom(roomId){cleanupRoom();activeRoomId=roomId;attachRoomChat(roomId);$("#arena-mode-label").textContent="RANKED 1V1";setView("arena-view");roomUnsub=onValue(ref(db,`rooms/${roomId}`),snap=>{roomState=snap.val();if(!roomState)return;roomState.selectedNumber=roomState.abilities?.selected?.[user.uid]??null;if(roomState.status==="finished"){renderRoomResult();return;}if(roomState.status==="playing"&&roomState.lastMoveAt&&roomState.turn===user.uid&&roomState.lastMoveAt!==listenRoom.lastMove){lastTurnAt=Date.now();listenRoom.lastMove=roomState.lastMoveAt;}updateArena();if(roomState.status==="setup"&&!readyTimer)startSetupCountdown();if(roomState.status==="playing"){clearInterval(readyTimer);readyTimer=null;startRoomTimer();}if(roomState.status==="finished")remove(ref(db,`users/${user.uid}/activeRoom`));});await set(ref(db,`rooms/${roomId}/presence/${user.uid}`),true);onDisconnect(ref(db,`rooms/${roomId}/presence/${user.uid}`)).set(false);const liveRoom=(await get(ref(db,`rooms/${roomId}`))).val();const opponent=(liveRoom?.players||[]).find(p=>p!==user.uid);if(!opponent)return;opponentPresenceUnsub=onValue(ref(db,`rooms/${roomId}/presence/${opponent}`),presence=>{if(presence.val()===false||!presence.exists()){clearTimeout(disconnectTimer);disconnectTimer=setTimeout(async()=>{const still=await get(ref(db,`rooms/${roomId}/presence/${opponent}`));if(!still.exists()||still.val()===false){await runTransaction(ref(db,`rooms/${roomId}`),room=>{if(!room||room.status!=="playing")return;room.status="finished";room.winner=user.uid;room.finishedAt=Date.now();return room;});}},20000);}else clearTimeout(disconnectTimer);});}
async function recoverRoom(){const id=userData?.activeRoom;if(!id)return;const s=await get(ref(db,`rooms/${id}`));if(s.exists()&&s.val().status!=="finished")listenRoom(id);else await remove(ref(db,`users/${user.uid}/activeRoom`));}
async function readyOnline(){clearInterval(readyTimer);readyTimer=null;if(!validBoard(setupBoard)){toast("Invalid board. Shuffle and try again.");return;}try{const roomRef=ref(db,`rooms/${activeRoomId}`);const tx=await runTransaction(roomRef,room=>{if(!room||room.status!=="setup")return;room.boards=room.boards||{};room.boards[user.uid]=setupBoard;room.ready=room.ready||{};room.ready[user.uid]=true;if(room.players.every(p=>room.ready[p])){room.status="playing";room.turn=room.players[0];room.turnStartedAt=Date.now();room.lastMoveAt=Date.now();}return room;});if(tx.committed){toast("Board locked.");}else toast("Could not lock board.");}catch(e){toast(e.message);}}
function startRoomTimer(){clearInterval(turnInterval);turnInterval=setInterval(()=>{if(!roomState||roomState.status!=="playing")return;const budget=15+Number(roomState.timeBonusSeconds||0),remain=Math.max(0,budget-Math.floor((Date.now()-(roomState.turnStartedAt||Date.now()))/1000));$("#turn-timer").textContent=remain;if(remain===0&&roomState.turn===user.uid){const board=roomState.boards[user.uid],n=board.find(x=>!roomState.calledNumbers.includes(x));if(n)callOnline(n);}},250);}
async function useOnlineAbility(type){if(!user||!activeRoomId||!roomState||roomState.status!=="playing"||roomState.turn!==user.uid)return toast("Abilities are available only on your turn.");const roomRef=ref(db,`rooms/${activeRoomId}`),uid=user.uid;let sonar=null;try{const tx=await runTransaction(roomRef,room=>{if(!room||room.status!=="playing"||room.turn!==uid)return;room.abilities=room.abilities||{charges:{},usedTurn:{},aegis:{}};const a=room.abilities;a.charges=a.charges||{};a.usedTurn=a.usedTurn||{};a.aegis=a.aegis||{};if(a.charges[uid]===undefined)a.charges[uid]=2;if(a.charges[uid]<=0||a.usedTurn[uid]===room.turnStartedAt)return;a.charges[uid]--;a.usedTurn[uid]=room.turnStartedAt;if(type==="chrono")room.timeBonusSeconds=Number(room.timeBonusSeconds||0)+5;if(type==="aegis")a.aegis[uid]=true;if(type==="sonar"){const board=room.boards[uid],calls=room.calledNumbers||[],pick=board.filter(n=>!calls.includes(n)).sort((x,y)=>linePotential(board,calls,y)-linePotential(board,calls,x))[0];a.selected=a.selected||{};a.selected[uid]=pick;sonar=pick;}return room;});if(!tx.committed)return toast("No ability charge available this turn.");if(sonar!==null){roomState.selectedNumber=sonar;$("#board-hint").textContent=`SONAR → ${sonar} advances the most open lines`;toast(`Sonar found ${sonar}.`);}else toast(type==="chrono"?"Chrono Surge +5 seconds.":"Aegis Ward active for the next opponent turn.");beep("tap");}catch(e){toast(e.message||"Ability unavailable.");}}
async function callOnline(n){const uid=user.uid,roomRef=ref(db,`rooms/${activeRoomId}`);lastTurnAt=Date.now();try{const tx=await runTransaction(roomRef,room=>{if(!room||room.status!=="playing"||room.turn!==uid||(room.calledNumbers||[]).includes(n))return;const caller=room.turn;room.calledNumbers=[...(room.calledNumbers||[]),n];room.abilities=room.abilities||{charges:{},usedTurn:{},aegis:{}};const counts=room.players.map(p=>evaluateBoardLines(room.boards[p],room.calledNumbers).length),winners=room.players.filter((p,i)=>counts[i]>=5),defender=room.players.find(p=>p!==caller);if(winners.length){room.status="finished";const side=resolveLineWinner(counts[0],counts[1],caller===room.players[0]?"player":"bot",Boolean(room.abilities.aegis?.[defender]));room.winner=side==="player"?room.players[0]:room.players[1];room.finishedAt=Date.now();}else{room.turn=defender;room.turnIndex=(room.turnIndex||0)+1;room.turnStartedAt=Date.now();room.lastMoveAt=Date.now();room.timeBonusSeconds=0;}if(room.abilities.aegis?.[defender])room.abilities.aegis[defender]=false;return room;});if(!tx.committed)toast("That move was not accepted.");else{beep("slash");vibrate();speakCallout(`Number ${n}`);}}catch(e){toast(e.message||"Move failed.");}}
function renderRoomResult(){clearInterval(turnInterval);if(roomState?.status!=="finished")return;const winner=roomState.winner;const win=winner===user.uid;$("#result-title").textContent=win?"Victory.":"Defeat.";$("#result-summary").textContent=`${win?"You completed":"Your opponent completed"} five lines. Both boards are revealed for verification.`;const opp=roomState.players.find(p=>p!==user.uid);renderReveal($("#reveal-mine"),roomState.boards[user.uid],roomState.calledNumbers||[]);renderReveal($("#reveal-opponent"),roomState.boards[opp],roomState.calledNumbers||[]);$("#playing-controls").classList.add("hidden");$("#setup-controls").classList.add("hidden");if(!renderRoomResult.shown){renderRoomResult.shown=true;modal("result-modal");}if(!awardedRooms.has(activeRoomId)){awardedRooms.add(activeRoomId);awardRankedResult(roomState,win);}update(ref(db,`users/${user.uid}`),{activeRoom:null,status:"online"});}
async function awardRankedResult(room,won){if(!user||!room||room.players?.length!==2)return;const opponent=room.players.find(p=>p!==user.uid),now=Date.now(),oppRef=ref(db,`users/${user.uid}/recentOpponents/${opponent}`);try{const cap=await runTransaction(oppRef,v=>{if(!v||now-v.windowStart>=86400000)return{count:1,windowStart:now};if(v.count>=2)return;return{count:v.count+1,windowStart:v.windowStart};});if(!cap.committed){toast("Rematch cap reached: this match is casual, no RP change.");return;}const statsRef=ref(db,`users/${user.uid}/stats`);await runTransaction(statsRef,stats=>{stats=stats||{matchesPlayed:0,wins:0,losses:0,winStreak:0};stats.matchesPlayed=Number(stats.matchesPlayed||0)+1;if(won){stats.wins=Number(stats.wins||0)+1;stats.winStreak=Number(stats.winStreak||0)+1;}else{stats.losses=Number(stats.losses||0)+1;stats.winStreak=0;}return stats;});const rpRef=ref(db,`users/${user.uid}/rp`),r=rankFor(Number(userData?.rp??100)),delta=won?r.win:-r.loss;let consumedShield=false;const result=await runTransaction(rpRef,value=>{let rp=Number(value??100);const shield=!!userData?.demotionShield,floor=r.floor>=1500?r.floor:null;if(!won&&floor&&shield&&rp+delta<floor){consumedShield=true;return floor;}return Math.max(0,rp+delta);});const nextRp=Number(result.snapshot.val()||0);if(consumedShield)await update(ref(db,`users/${user.uid}`),{demotionShield:false});else if(nextRp>=2200&&!userData?.demotionShield)await update(ref(db,`users/${user.uid}`),{demotionShield:true});else if(nextRp>=1500&&nextRp<2200&&!userData?.demotionShield)await update(ref(db,`users/${user.uid}`),{demotionShield:true});if(won)toast(`Victory · +${delta} RP`);else toast(`Defeat · ${delta} RP`);}catch(e){console.warn("Rank update failed",e);}}
