function staffPanel(){if(!user)return;const role=userData?.role||"player";if(role==="player"&&user.uid!==PRIMARY_OWNER_UID){toast("Staff authorization required.");return;}modal("staff-modal");renderStaffTab("overview");}
async function logStaff(action,target){if(!user)return;try{await push(ref(db,"auditLogs"),{actorUid:user.uid,actorName:userData?.username||user.displayName,role:userData?.role||"owner",action,target:String(target||""),timestamp:serverTimestamp()});}catch(e){console.warn("Audit write denied",e);}}
async function staffCreateCode(owner){const code=$("#new-code").value.trim().toUpperCase(),[type,rewardId]=$("#new-reward").value.split(":"),maxUses=Number($("#code-uses").value);if(!code||!maxUses)return toast("Enter a code and valid use limit.");if(rewardId==="overdrive"&&!owner)return toast("Only the Owner can create Admin Bundle codes.");try{await set(ref(db,`redeemCodes/${code}`),{type,rewardId:rewardId==="overdrive"?"admin_bundle":rewardId,maxUses,usedCount:0,active:true,redeemedBy:{}});await logStaff("create_redeem_code",code);toast("Code created.");}catch(e){toast(e.message||"Code creation denied.");}}
async function staffAnnouncement(){const text=$("#announcement").value.trim();try{await set(ref(db,"system/announcement"),text||null);await logStaff("announcement",text);toast("Announcement updated.");}catch(e){toast(e.message);}}
function staffIsOwner(){return user?.uid===PRIMARY_OWNER_UID||userData?.role==="owner";}
function staffIsSuper(){return staffIsOwner()||userData?.role==="super_admin";}
async function uidByName(name){const clean=String(name||"").trim().toLowerCase();if(!clean)return null;const s=await get(ref(db,"usernames/"+clean));return s.val()||null;}
function renderStaffTab(tab){$$(".staff-tabs button").forEach(b=>b.classList.toggle("active",b.dataset.staffTab===tab));const c=$("#staff-content"),superAdmin=staffIsSuper(),owner=staffIsOwner();const staffRPControl=superAdmin?'<input id="staff-rp" type="number" placeholder="RP adjustment"><button class="button button-primary" id="staff-rp-apply">Apply RP change</button>':"";const staffCosmeticControl=superAdmin?'<select id="staff-cosmetic"><option value="skin:midnight">Grant Midnight Blue skin</option><option value="title:Discord Insider">Grant Discord Insider title</option>'+(owner?'<option value="bundle:admin_bundle">Grant Admin Bundle</option>':"")+'</select><button class="button button-outline" id="staff-grant">Grant cosmetic</button>':"";const staffRoleControl=owner?'<select id="staff-new-role"><option value="admin">Promote to Admin</option><option value="super_admin">Promote to Super Admin</option><option value="player">Demote to Player</option></select><button class="button button-outline" id="staff-role-apply">Update role</button>':"";if(tab==="overview"){c.innerHTML=`<div class="staff-summary"><span>ROLE<b>${escapeHtml(owner?"OWNER":userData.role.toUpperCase())}</b></span><span>TOOLS<b>Moderation · Reports</b></span></div><h3>Quick action templates</h3><div class="template-chips"><button data-template-action="mute24">Chat Spam Mute · 24h</button><button data-template-action="ban7">Unsportsmanlike Conduct · 7d</button><button data-template-action="rp50">Tournament RP Bonus · +50</button><button data-template-action="grant">Discord Giveaway Grant</button><button data-template-action="clear">Clear Penalties</button></div><div class="staff-form"><input id="staff-target" placeholder="Player username"><select id="staff-action"><option value="mute24">Mute · 24 hours</option><option value="unmute">Unmute</option><option value="ban7">Ban · 7 days</option><option value="unban">Unban</option><option value="clear">Clear all penalties</option>${superAdmin?'<option value="mutepermanent">Permanent mute</option><option value="banpermanent">Permanent ban</option>':""}</select><button class="button button-primary" id="staff-apply">Apply action</button></div><p class="muted">Staff actions are audit logged. Target players by username.</p>`;$("#staff-apply").addEventListener("click",staffModerate);$$("[data-template-action]").forEach(b=>b.addEventListener("click",()=>applyStaffTemplate(b.dataset.templateAction)));return;}if(tab==="players"){c.innerHTML=`<div class="staff-directory-head"><p class="muted">Username-first player directory.</p><input id="directory-search" placeholder="Search players"></div><div id="staff-directory" class="staff-directory">Loading players…</div><div class="staff-action-drawer hidden" id="staff-action-drawer"><h3 id="staff-selected-name">Player</h3><div class="staff-form"><input id="staff-target" placeholder="Player username">${staffRPControl}${staffCosmeticControl}${staffRoleControl}</div></div>`;loadStaffDirectory();return;}if(tab==="codes"){if(!superAdmin){c.innerHTML='<p class="muted">Code and announcement tools require Super Admin or Owner.</p>';return;}c.innerHTML=`<p class="muted">Create an event code or update the global lobby banner.</p><div class="staff-form"><input id="new-code" placeholder="REDEEM CODE"><select id="new-reward"><option value="skin:midnight">Midnight Blue skin</option><option value="skin:crimson">Crimson Dark skin</option><option value="title:Discord Insider">Discord Insider title</option>${owner?'<option value="bundle:admin_bundle">Admin Bundle</option>':""}</select><input id="code-uses" type="number" min="1" value="1"><button class="button button-primary" id="code-create">Create code</button><input id="announcement" class="span-two" placeholder="Global announcement"><button class="button button-outline" id="announcement-set">Post announcement</button><button class="button button-quiet" id="announcement-clear">Clear banner</button></div>`;$("#code-create").addEventListener("click",()=>staffCreateCode(owner));$("#announcement-set").addEventListener("click",staffAnnouncement);$("#announcement-clear").addEventListener("click",async()=>{await set(ref(db,"system/announcement"),null);logStaff("announcement_clear","global");toast("Announcement cleared.");});return;}if(tab==="messages"){if(!superAdmin){c.innerHTML='<p class="muted">Mailbox messaging is limited to Super Admin and Owner.</p>';return;}c.innerHTML=`<p class="muted">Send to one username or broadcast to registered players.</p><div class="mail-templates"><button data-mail-template="Discord Event Reward">Discord Event Reward</button><button data-mail-template="Fair Play / Rule Warning">Fair Play / Rule Warning</button><button data-mail-template="Scheduled Maintenance Notice">Scheduled Maintenance Notice</button><button data-mail-template="Rank Adjustment / Tournament Notice">Rank Adjustment / Tournament Notice</button></div><div class="staff-form"><input id="staff-mail-target" placeholder="Target username"><label class="broadcast-toggle"><input type="checkbox" id="mail-broadcast"> Broadcast to all players</label><input id="staff-mail-subject" placeholder="Subject"><select id="mail-theme"><option value="normal">Normal Theme</option><option value="crimson">Crimson Red Alert</option><option value="heavenly">Heavenly Reward</option></select><textarea id="staff-mail-body" placeholder="Write a message to the mailbox…" maxlength="1000"></textarea><button class="button button-primary" id="staff-mail-send">Send mailbox message</button></div>`;$$("[data-mail-template]").forEach(b=>b.addEventListener("click",()=>{$("#staff-mail-subject").value=b.dataset.mailTemplate;$("#staff-mail-body").value=mailTemplateBody(b.dataset.mailTemplate);}));$("#staff-mail-send").addEventListener("click",sendStaffMailbox);return;}if(tab==="reports"){if(!owner){c.innerHTML='<p class="muted">Owner-only reports center.</p>';return;}c.innerHTML=`<p class="muted">Platform snapshots and audit exports. Reports use usernames instead of raw IDs.</p><div class="report-actions"><button class="button button-outline" data-report="players">Player &amp; rank distribution</button><button class="button button-outline" data-report="codes">Redeem &amp; bundle audit</button><button class="button button-outline" data-report="audit">Moderation &amp; audit log</button></div><pre id="report-output" class="report-output">Choose a report to generate.</pre><div class="modal-actions"><button class="button button-outline" id="report-copy">Copy report</button><button class="button button-primary" id="report-download">Download JSON</button></div>`;$$("[data-report]").forEach(b=>b.addEventListener("click",()=>generateOwnerReport(b.dataset.report)));$("#report-copy").addEventListener("click",async()=>{try{await navigator.clipboard.writeText($("#report-output").textContent);toast("Report copied.");}catch{toast("Clipboard unavailable.");}});$("#report-download").addEventListener("click",downloadOwnerReport);return;}if(tab==="audit"){if(!superAdmin){c.innerHTML='<p class="muted">Audit log access requires Super Admin or Owner.</p>';return;}c.innerHTML='<p class="muted">Read-only staff activity log.</p><pre id="audit-view" class="audit-view">Loading…</pre>';sanitizedAuditLogs().then(entries=>{$("#audit-view").textContent=JSON.stringify(entries,null,2);});}}
async function loadStaffDirectory(){try{const s=await get(ref(db,"usernames")),entries=Object.entries(s.val()||{});usersCache={};const rows=await Promise.all(entries.map(async([name,uid])=>{const keys=["rp","status","role","avatarPreset","avatarUrl","bannedUntil","lastSeen","equippedFrame"],vals=await Promise.all(keys.map(k=>get(ref(db,`users/${uid}/${k}`))));const d=Object.fromEntries(keys.map((k,i)=>[k,vals[i].val()]));d.username=name;usersCache[uid]=d;return`<button class="directory-card" data-directory-uid="${uid}" data-directory-name="${escapeHtml(name)}"><span class="directory-avatar">${escapeHtml(name[0].toUpperCase())}</span><span class="directory-copy"><b>@${escapeHtml(name)}</b><small>${rankFor(Number(d.rp||100)).name} · ${Number(d.rp||100)} RP · ${escapeHtml(d.role||"player")}</small></span><span class="directory-status ${d.status==="online"?"online":""}">${d.bannedUntil&&d.bannedUntil>Date.now()?"Banned":d.status==="in_game"?"In Match":d.status==="online"?"Online":`Offline · ${timeAgo(d.lastSeen)}`}</span></button>`;}));$("#staff-directory").innerHTML=rows.join("")||'<p class="muted">No registered players yet.</p>';$("#directory-search").addEventListener("input",e=>{$$(".directory-card").forEach(row=>row.classList.toggle("hidden",!row.dataset.directoryName.includes(e.target.value.toLowerCase())));});$("#staff-directory").addEventListener("click",e=>{const card=e.target.closest("[data-directory-uid]");if(!card)return;$("#staff-target").value=card.dataset.directoryName;$("#staff-selected-name").textContent="@"+card.dataset.directoryName;$("#staff-action-drawer").classList.remove("hidden");const rpButton=$("#staff-rp-apply");if(rpButton)rpButton.addEventListener("click",staffAdjustRP);const grant=$("#staff-grant");if(grant)grant.addEventListener("click",staffGrantCosmetic);const role=$("#staff-role-apply");if(role)role.addEventListener("click",staffChangeRole);});}catch(e){$("#staff-directory").textContent="Could not load directory. Check staff read rules.";}}
async function applyStaffTemplate(id){if(id==="mute24")$("#staff-action").value="mute24";if(id==="ban7")$("#staff-action").value="ban7";if(id==="clear")$("#staff-action").value="clear";if(id==="rp50"){if(!staffIsSuper())return toast("Super Admin permission required.");const name=prompt("Username for +50 RP bonus");if(!name)return;renderStaffTab("players");setTimeout(()=>{$("#staff-target").value=name.trim().toLowerCase();$("#staff-selected-name").textContent="@"+name.trim();$("#staff-action-drawer").classList.remove("hidden");$("#staff-rp").value=50;$("#staff-rp-apply").addEventListener("click",staffAdjustRP);},0);}if(id==="grant")renderStaffTab("players");}
async function staffModerate(){const name=$("#staff-target")?.value.trim().toLowerCase(),action=$("#staff-action")?.value;if(!name)return toast("Enter a player username.");try{const uid=await uidByName(name);if(!uid)return toast("No player has that username.");if(uid===PRIMARY_OWNER_UID)return toast("The primary owner is protected.");const isSuper=staffIsSuper();if((action==="mutepermanent"||action==="banpermanent")&&!isSuper)return toast("Only Super Admin or Owner can apply permanent actions.");const values={mute24:{mutedUntil:Date.now()+86400000},mutepermanent:{mutedUntil:-1},unmute:{mutedUntil:0},ban7:{bannedUntil:Date.now()+604800000},banpermanent:{bannedUntil:-1},unban:{bannedUntil:0},clear:{bannedUntil:0,mutedUntil:0}};await update(ref(db,`users/${uid}`),values[action]);await logStaff(action,name);toast("Moderation action applied.");}catch(e){console.error("Staff moderation failed",e.code,e.message);toast(e.message||"Staff action was denied.");}}
async function staffAdjustRP(){if(!staffIsSuper())return toast("Super Admin or Owner permission required.");const name=$("#staff-target")?.value.trim().toLowerCase(),delta=Number($("#staff-rp")?.value);if(!name||!Number.isFinite(delta))return toast("Enter a player username and RP adjustment.");if(Math.abs(delta)>100&&!staffIsOwner())return toast("Super Admin adjustments are capped at ±100 RP.");try{const uid=await uidByName(name);if(!uid)return toast("No player has that username.");if(uid===PRIMARY_OWNER_UID&&!staffIsOwner())return toast("The primary owner is protected.");const rpRef=ref(db,`users/${uid}/rp`),tx=await runTransaction(rpRef,rp=>Math.max(0,Number(rp||100)+delta));if(tx.committed){await logStaff(`rp:${delta}`,name);toast("RP adjustment saved.");}}catch(e){toast(e.message||"RP update failed.");}}
async function staffGrantCosmetic(){if(!staffIsSuper())return toast("Super Admin or Owner permission required.");const name=$("#staff-target").value.trim().toLowerCase(),[kind,value]=$("#staff-cosmetic").value.split(":");try{const uid=await uidByName(name);if(!uid)return toast("Player not found.");const changes=kind==="bundle"?{"unlockedSkins/overdrive":true,"unlockedTitles/[SYSTEM ARCHITECT]":true}:{[kind==="skin"?`unlockedSkins/${value}`:`unlockedTitles/${value}`]:true};await update(ref(db,`users/${uid}`),changes);await logStaff("grant_cosmetic",`${name}:${value}`);toast("Cosmetic granted.");}catch(e){toast(e.message||"Grant denied.");}}
async function staffChangeRole(){if(!staffIsOwner())return toast("Owner permission required.");const name=$("#staff-target").value.trim().toLowerCase(),role=$("#staff-new-role").value;try{const uid=await uidByName(name);if(!uid||uid===PRIMARY_OWNER_UID)return toast("That player cannot be modified.");await update(ref(db,`users/${uid}`),{role});await logStaff("role_change",`${name}:${role}`);toast("Role updated.");}catch(e){toast(e.message||"Role change denied.");}}
function mailTemplateBody(subject){return({"Discord Event Reward":"Thanks for joining the Anlossa Group Discord event. Your reward is ready in your Locker.","Fair Play / Rule Warning":"A reminder to keep Bingo 25 matches respectful and fair. Please review the community rules before your next match.","Scheduled Maintenance Notice":"Bingo 25 will have scheduled maintenance soon. Your current match may be unavailable during this window.","Rank Adjustment / Tournament Notice":"Your rank profile has been updated. Check the lobby for tournament details."})[subject]||"";}
async function sendStaffMailbox(){if(!staffIsSuper())return toast("Mailbox composer is Super Admin / Owner only.");const subject=$("#staff-mail-subject").value.trim(),body=$("#staff-mail-body").value.trim(),theme=$("#mail-theme").value,broadcast=$("#mail-broadcast").checked;if(!subject||!body)return toast("Add a subject and message.");try{let recipients=[];if(broadcast){const s=await get(ref(db,"usernames"));recipients=Object.values(s.val()||{});}else{const uid=await uidByName($("#staff-mail-target").value);if(!uid)return toast("Choose a valid username.");recipients=[uid];}await Promise.all(recipients.map(async uid=>{const msgRef=push(ref(db,`users/${uid}/mailbox`)),status=await get(ref(db,`users/${uid}/status`));await set(msgRef,{subject,body,theme,senderName:userData?.username||"Anlossa Staff",read:false,deleted:false,createdAt:serverTimestamp()});if(status.val()==="online"){const alertRef=push(ref(db,`users/${uid}/liveAlerts`));await set(alertRef,{subject,body,theme,senderName:userData?.username||"Anlossa Staff",createdAt:serverTimestamp()});}}));await logStaff("mailbox_send",broadcast?`broadcast:${recipients.length}`:$("#staff-mail-target").value);toast(`Message delivered to ${recipients.length} player${recipients.length===1?"":"s"}.`);}catch(e){console.error("Mailbox delivery failed",e.code,e.message);toast(e.message||"Could not deliver mailbox message.");}}
let ownerReportData=null;
async function sanitizedAuditLogs(){const [logsSnap,namesSnap]=await Promise.all([get(ref(db,"auditLogs")),get(ref(db,"usernames"))]);const uidToName=Object.fromEntries(Object.entries(namesSnap.val()||{}).map(([name,uid])=>[uid,name]));return Object.values(logsSnap.val()||{}).map(({actorUid,...entry})=>{let target=String(entry.target||"");if(uidToName[target])target="@"+uidToName[target];else if(/^[A-Za-z0-9_-]{20,}$/.test(target))target="Player";return{...entry,actorName:entry.actorName||uidToName[actorUid]||"Staff",target};});}
async function generateOwnerReport(type){if(!staffIsOwner())return toast("Owner only.");const output=$("#report-output");output.textContent="Generating…";try{let report;if(type==="players"){const s=await get(ref(db,"usernames")),players=Object.entries(s.val()||{}),groups=Object.fromEntries(RANKS.map(r=>[r.name,0]));let onlineNow=0;for(const [username,uid] of players){const [rpSnap,statusSnap]=await Promise.all([get(ref(db,`users/${uid}/rp`)),get(ref(db,`users/${uid}/status`))]);groups[rankFor(Number(rpSnap.val()||100)).name]++;if(statusSnap.val()==="online")onlineNow++;}report={generatedAt:new Date().toISOString(),totalPlayers:players.length,onlineNow,rankDistribution:groups};}else if(type==="codes"){const s=await get(ref(db,"redeemCodes")),codes=s.val()||{};report={generatedAt:new Date().toISOString(),codes:Object.fromEntries(Object.entries(codes).map(([code,d])=>[code,{type:d.type,rewardId:d.rewardId,maxUses:d.maxUses,usedCount:d.usedCount,active:d.active,redeemedCount:Object.keys(d.redeemedBy||{}).length}]))};}else{report={generatedAt:new Date().toISOString(),auditLogs:await sanitizedAuditLogs()};}ownerReportData=report;output.textContent=JSON.stringify(report,null,2);}catch(e){output.textContent=`Report unavailable: ${e.message||"check owner read rules"}`;}}
async function downloadOwnerReport(){if(!ownerReportData)return toast("Generate a report first.");const blob=new Blob([JSON.stringify(ownerReportData,null,2)],{type:"application/json"}),a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`bingo25-report-${Date.now()}.json`;a.click();URL.revokeObjectURL(a.href);}
